use ledger::Ledger;

/// Apply every record of a statement and render the account report.
///
/// Accounts are sorted by name, the header is the user supplied
/// [`user_policy::REPORT_HEADER`], every account line is `account,amount` with
/// two fraction digits, and the report ends with a newline. Any parsing or
/// bookkeeping error aborts the whole run and returns `Err`, so callers never
/// see a partially applied report.
pub fn run(input: &str) -> Result<String, String> {
    let mut ledger = Ledger::new();
    for event in parse_events(input)? {
        ledger.apply(&event)?;
    }

    let mut output = String::new();
    output.push_str(user_policy::REPORT_HEADER);
    output.push('\n');
    for (account, cents) in ledger.balances() {
        output.push_str(account);
        output.push(',');
        output.push_str(&format_cents(*cents));
        output.push('\n');
    }
    Ok(output)
}

